-- ===== VIEWS =====
CREATE OR REPLACE VIEW "contractor_full_view" AS
 SELECT cd.id AS contractor_detail_id,
    cd."tenantId" AS client_tenant_id,
    cd."organizationId",
    cd."linkedTenantId",
    cd.status AS contractor_status,
    o."legalName" AS business_name,
    o."taxId" AS tax_id,
    o."primaryContactEmail" AS org_email,
    o.phone AS org_phone,
    o.address AS org_address,
    o.country,
    o.city,
    cd."contactEmail" AS override_email,
    cd."contactPhone" AS override_phone,
    cd.address AS override_address,
    COALESCE(cd."contactEmail", o."primaryContactEmail") AS effective_email,
    COALESCE(cd."contactPhone", o.phone) AS effective_phone,
    COALESCE(cd.address, o.address::character varying) AS effective_address,
    t.name AS client_tenant_name,
    lt.name AS contractor_tenant_name
   FROM "ContractorRegistrations" cd
     JOIN "Organizations" o ON cd."organizationId" = o.id
     JOIN "Tenants" t ON cd."tenantId" = t.id
     LEFT JOIN "Tenants" lt ON cd."linkedTenantId" = lt.id
  WHERE cd."deletedAt" IS NULL;

